#include <stdio.h>
#include <string.h>

void compareStrings(char str1[], char str2[]) {
    if (strcmp(str1, str2) == 0)
        printf("Strings are equal.\n");
    else
        printf("Strings are not equal.\n");
}

void findLongerString(char str1[], char str2[]) {
    int len1 = strlen(str1);
    int len2 = strlen(str2);

    if (len1 > len2)
        printf("First string is longer.\n");
    else if (len2 > len1)
        printf("Second string is longer.\n");
    else
        printf("Both strings are of equal length.\n");
}

void concatenateStrings(char str1[], char str2[]) {
    char result[200]; 
    strcpy(result, str1);
    strcat(result, str2);
    printf("Concatenated String: %s\n", result);
}

void findSubstring(char str1[], char str2[]) {
    if (strstr(str1, str2) != NULL)
        printf("Substring found in the main string.\n");
    else
        printf("Substring not found.\n");
}

int main() {
    char str1[100], str2[100];
    int choice;

    printf("Enter first string: ");
    fgets(str1, sizeof(str1), stdin);
    str1[strcspn(str1, "\n")] = '\0';

    printf("Enter second string: ");
    fgets(str2, sizeof(str2), stdin);
    str2[strcspn(str2, "\n")] = '\0';

    do {
        printf("\nMenu:\n");
        printf("1. Compare Strings\n");
        printf("2. Find Longer String\n");
        printf("3. Concatenate Strings\n");
        printf("4. Find Substring\n");
        printf("5. Exit\n");
        printf("Enter your choice: ");
        scanf("%d", &choice);
        getchar(); 

        switch (choice) {
            case 1:
                compareStrings(str1, str2);
                break;
            case 2:
                findLongerString(str1, str2);
                break;
            case 3:
                concatenateStrings(str1, str2);
                break;
            case 4:
                findSubstring(str1, str2);
                break;
            case 5:
                printf("Exiting program...\n");
                break;
            default:
                printf("Invalid choice, try again.\n");
        }
    } while (choice != 5);

    return 0;
}
```

### **How the Program Works**
1. The user enters **two strings**.
2. A **menu** is displayed inside a **do-while loop**, allowing the user to choose operations.
3. Based on the **user's choice**, one of the following functions is executed:
   - **Compare Strings (`strcmp()`)**
   - **Find Longer String (`strlen()`)**
   - **Concatenate Strings (`strcat()`)**
   - **Find Substring (`strstr()`)**
4. The menu **keeps appearing** until the user selects **option 5 (Exit).**

