int countVowels(char str[]) {
    int count = 0, i = 0;
    while (str[i] != '\0') {
        char c = str[i];
        if (c == 'A' || c == 'E' || c == 'I' || c == 'O' || c == 'U' ||
            c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') {
            count++;
        }
        i++;
    }
    return count;
}

int countSubstringOccurrences(char mainStr[], char subStr[]) {
    int count = 0, mainLen = strlen(mainStr), subLen = strlen(subStr);
    for (int i = 0; i <= mainLen - subLen; i++) {
        int found = 1;
        for (int j = 0; j < subLen; j++) {
            if (mainStr[i + j] != subStr[j]) {
                found = 0;
                break;
            }
        }
        if (found) count++;
    }
    return count;
}

