### **📌 Step 3: Write the Code**
```c
#include <stdio.h>

int main() {
    int n, i, key, found = 0;

    // Step 1: Take input for array size
    printf("Enter the number of elements: ");
    scanf("%d", &n);

    int arr[n]; // Declare an array of size 'n'

    // Step 2: Take input for array elements
    printf("Enter %d elements:\n", n);
    for (i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }

    // Step 3: Take input for the element to search
    printf("Enter the element to search: ");
    scanf("%d", &key);

    // Step 4: Search for the element using Linear Search
    for (i = 0; i < n; i++) {
        if (arr[i] == key) {
            printf("Element %d found at index %d\n", key, i);
            found = 1; // Mark as found
            break; // Exit loop as we found the element
        }
    }

    // Step 5: If element is not found, print message
    if (!found) {
        printf("Element not found in the array.\n");
    }

    return 0;
}
