        if (str[i] == '\n') {
            str[i] = '\0';  // Replace newline with null terminator
            break;
        }
        len++;
    }

    // Print reversed string
    printf("Reversed string: ");
    for (int i = len - 1; i >= 0; i--) { 
        printf("%c", str[i]);
        rev[len - 1 - i] = str[i];  // Store reversed string
    }
    rev[len] = '\0';  // Null terminate reversed string

    // Check if palindrome
    for (int i = 0; i < len; i++) {
        if (str[i] != rev[i]) {
            isPalindrome = 0; // Not a palindrome
            break;
        }
    }

    // Print result
    if (isPalindrome)
        printf("\nThe string is a palindrome.\n");
    else
        printf("\nThe string is NOT a palindrome.\n");
}
```

