### **C Code for Airline Database**
```c
#include <stdio.h>
#include <string.h>

#define MAX_FLIGHTS 100

struct Flight {
    int flightNo;
    char flightName[50];
    float price;
};

// Function to add a flight
void addFlight(struct Flight *flights, int *count) {
    if (*count >= MAX_FLIGHTS) {
        printf("Database is full!\n");
        return;
    }

    struct Flight *record = &flights[*count];

    printf("Enter Flight Number: ");
    scanf("%d", &record->flightNo);

    printf("Enter Flight Name: ");
    scanf(" %[^\n]s", record->flightName);

    printf("Enter Flight Price: ");
    scanf("%f", &record->price);

    (*count)++;
    printf("Flight added successfully!\n");
}

// Function to display all flights
void displayFlights(struct Flight *flights, int count) {
    if (count == 0) {
        printf("No flights in the database.\n");
        return;
    }

    printf("\n--- Flight Details ---\n");
    for (int i = 0; i < count; i++) {
        printf("Flight No: %d\n", flights[i].flightNo);
        printf("Flight Name: %s\n", flights[i].flightName);
        printf("Price: $%.2f\n\n", flights[i].price);
    }
}

int main() {
    struct Flight flights[MAX_FLIGHTS];
    int count = 0;
    int choice;

    while (1) {
        printf("\n--- Airline Database Menu ---\n");
        printf("1. Add Flight\n");
        printf("2. Display Flights\n");
