### **C Code: Accessing Nested Structure**
```c
#include <stdio.h>
#include <string.h>

// Structure for legendary Pokémon
struct legendary_pokemon {
    char ability[50]; // Extra ability only for legendary Pokémon
};

// Structure for Pokémon
struct pokemon {
    char name[50];
    int level;
    struct legendary_pokemon legendary; // Nested structure
    int isLegendary;  // Flag to check if Pokémon is legendary
};

int main() {
    // Creating a normal Pokémon
    struct pokemon pikachu;
    strcpy(pikachu.name, "Pikachu");
    pikachu.level = 35;
    pikachu.isLegendary = 0; // Not a legendary Pokémon

    // Creating a legendary Pokémon
    struct pokemon mewtwo;
    strcpy(mewtwo.name, "Mewtwo");
    mewtwo.level = 70;
    mewtwo.isLegendary = 1; // Mark as legendary
    strcpy(mewtwo.legendary.ability, "Pressure"); // Assign extra ability

    // Display normal Pokémon
    printf("Pokemon: %s\n", pikachu.name);
    printf("Level: %d\n", pikachu.level);
    if (pikachu.isLegendary) {
        printf("Ability: %s\n", pikachu.legendary.ability); 
